#### Live Regions for Dynamic Content

```html
<!-- Status messages -->
<div aria-live="polite" aria-atomic="true" id="status-region" class="sr-only">
    <!-- Status messages inserted here via JavaScript -->
</div>

<div aria-live="assertive" aria-atomic="true" id="error-region" class="sr-only">
    <!-- Critical error messages inserted here via JavaScript -->
</div>

<!-- Loading states -->
<div id="loading-indicator" aria-live="polite" aria-busy="true" aria-label="Loading user data">
    <span class="loading-spinner" aria-hidden="true"></span>
    Loading...
</div>
```

```javascript
// JavaScript for managing live regions
class AccessibilityAnnouncer {
    constructor() {
        this.politeRegion = document.getElementById('status-region');
        this.assertiveRegion = document.getElementById('error-region');
    }

    announceStatus(message) {
        this.politeRegion.textContent = message;
        // Clear after 5 seconds to prevent accumulation
        setTimeout(() => {
            this.politeRegion.textContent = '';
        }, 5000);
    }

    announceError(message) {
        this.assertiveRegion.textContent = message;
        setTimeout(() => {
            this.assertiveRegion.textContent = '';
        }, 10000);
    }

    announceLoading(isLoading, message = '') {
        const loadingIndicator = document.getElementById('loading-indicator');
        if (isLoading) {
            loadingIndicator.setAttribute('aria-busy', 'true');
            loadingIndicator.setAttribute('aria-label', message || 'Loading');
            loadingIndicator.style.display = 'block';
        } else {
            loadingIndicator.setAttribute('aria-busy', 'false');
            loadingIndicator.style.display = 'none';
        }
    }
}

// Usage
const announcer = new AccessibilityAnnouncer();

// Announce successful form submission
announcer.announceStatus('User successfully created');

// Announce validation errors
announcer.announceError('Please correct the highlighted errors');

// Announce loading states
announcer.announceLoading(true, 'Saving user data');
