[standards/application/accessibility/STD-APP-ACC-001-accessibility.md#keyboard-event-handling]

#### Keyboard Event Handling

```javascript
// Keyboard navigation for custom components
class AccessibleDropdown {
    constructor(element) {
        this.dropdown = element;
        this.trigger = element.querySelector('[aria-haspopup]');
        this.menu = element.querySelector('[role="menu"]');
        this.menuItems = Array.from(element.querySelectorAll('[role="menuitem"]'));
        this.isOpen = false;
        this.currentIndex = -1;

        this.bindEvents();
    }

    bindEvents() {
        // Trigger events
        this.trigger.addEventListener('click', this.toggle.bind(this));
        this.trigger.addEventListener('keydown', this.handleTriggerKeydown.bind(this));

        // Menu item events
        this.menuItems.forEach((item, index) => {
            item.addEventListener('keydown', (e) => this.handleMenuKeydown(e, index));
            item.addEventListener('click', this.handleMenuItemClick.bind(this));
        });

        // Close on outside click
        document.addEventListener('click', this.handleOutsideClick.bind(this));
    }

    toggle() {
        if (this.isOpen) {
            this.close();
        } else {
            this.open();
        }
    }

    open() {
        this.isOpen = true;
        this.menu.removeAttribute('hidden');
        this.trigger.setAttribute('aria-expanded', 'true');
        this.focusFirstMenuItem();
    }

    close() {
        this.isOpen = false;
        this.menu.setAttribute('hidden', '');
        this.trigger.setAttribute('aria-expanded', 'false');
        this.trigger.focus();
        this.currentIndex = -1;
    }

    handleTriggerKeydown(event) {
        switch (event.key) {
            case 'Enter':
            case ' ':
            case 'ArrowDown':
                event.preventDefault();
                this.open();
                break;
            case 'ArrowUp':
                event.preventDefault();
                this.open();
                this.focusLastMenuItem();
                break;
            case 'Escape':
                this.close();
                break;
        }
    }

    handleMenuKeydown(event, index) {
        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                this.focusNextMenuItem();
                break;
            case 'ArrowUp':
                event.preventDefault();
                this.focusPreviousMenuItem();
                break;
            case 'Home':
                event.preventDefault();
                this.focusFirstMenuItem();
                break;
            case 'End':
                event.preventDefault();
                this.focusLastMenuItem();
                break;
            case 'Escape':
                this.close();
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this.menuItems[index].click();
                break;
        }
    }

    focusFirstMenuItem() {
        this.currentIndex = 0;
        this.menuItems[0].focus();
    }

    focusLastMenuItem() {
        this.currentIndex = this.menuItems.length - 1;
        this.menuItems[this.currentIndex].focus();
    }

    focusNextMenuItem() {
        this.currentIndex = (this.currentIndex + 1) % this.menuItems.length;
        this.menuItems[this.currentIndex].focus();
    }

    focusPreviousMenuItem() {
        this.currentIndex =
            this.currentIndex <= 0 ? this.menuItems.length - 1 : this.currentIndex - 1;
        this.menuItems[this.currentIndex].focus();
    }

    handleMenuItemClick() {
        this.close();
    }

    handleOutsideClick(event) {
        if (this.isOpen && !this.dropdown.contains(event.target)) {
            this.close();
        }
    }
}

// Initialize all dropdowns
document.querySelectorAll('.dropdown').forEach((dropdown) => {
    new AccessibleDropdown(dropdown);
});
```

