[standards/application/accessibility/STD-APP-ACC-001-accessibility.md#focus-trap-for-modals]

#### Focus Trap for Modals

```javascript
class AccessibleModal {
    constructor(modalElement) {
        this.modal = modalElement;
        this.overlay = modalElement.querySelector('.modal-overlay');
        this.content = modalElement.querySelector('.modal-content');
        this.closeButton = modalElement.querySelector('.modal-close');
        this.focusableElements = this.getFocusableElements();
        this.firstFocusable = this.focusableElements[0];
        this.lastFocusable = this.focusableElements[this.focusableElements.length - 1];
        this.previouslyFocused = null;

        this.bindEvents();
    }

    getFocusableElements() {
        const focusableSelectors = [
            'button:not([disabled])',
            'input:not([disabled])',
            'textarea:not([disabled])',
            'select:not([disabled])',
            'a[href]',
            '[tabindex]:not([tabindex="-1"])',
        ].join(',');

        return Array.from(this.content.querySelectorAll(focusableSelectors));
    }

    bindEvents() {
        // Close events
        this.closeButton.addEventListener('click', this.close.bind(this));
        this.overlay.addEventListener('click', this.close.bind(this));

        // Keyboard events
        this.modal.addEventListener('keydown', this.handleKeydown.bind(this));
    }

    open() {
        // Store previously focused element
        this.previouslyFocused = document.activeElement;

        // Show modal
        this.modal.removeAttribute('hidden');
        this.modal.setAttribute('aria-modal', 'true');

        // Prevent body scroll
        document.body.style.overflow = 'hidden';

        // Focus first element
        if (this.firstFocusable) {
            this.firstFocusable.focus();
        }
    }

    close() {
        // Hide modal
        this.modal.setAttribute('hidden', '');
        this.modal.removeAttribute('aria-modal');

        // Restore body scroll
        document.body.style.overflow = '';

        // Restore focus
        if (this.previouslyFocused) {
            this.previouslyFocused.focus();
        }
    }

    handleKeydown(event) {
        if (event.key === 'Escape') {
            this.close();
            return;
        }

        if (event.key === 'Tab') {
            this.trapFocus(event);
        }
    }

    trapFocus(event) {
        if (this.focusableElements.length === 0) return;

        if (event.shiftKey) {
            // Shift + Tab
            if (document.activeElement === this.firstFocusable) {
                event.preventDefault();
                this.lastFocusable.focus();
            }
        } else {
            // Tab
            if (document.activeElement === this.lastFocusable) {
                event.preventDefault();
                this.firstFocusable.focus();
            }
        }
    }
}
