[standards/application/accessibility/STD-APP-ACC-001-accessibility.md#form-validation-with-accessibility]

#### Form Validation with Accessibility

```javascript
class AccessibleFormValidator {
    constructor(form) {
        this.form = form;
        this.fields = Array.from(form.querySelectorAll('input, textarea, select'));
        this.announcer = new AccessibilityAnnouncer();

        this.bindEvents();
    }

    bindEvents() {
        this.form.addEventListener('submit', this.handleSubmit.bind(this));

        this.fields.forEach((field) => {
            field.addEventListener('blur', this.validateField.bind(this));
            field.addEventListener('input', this.clearFieldError.bind(this));
        });
    }

    handleSubmit(event) {
        event.preventDefault();

        const isValid = this.validateForm();

        if (isValid) {
            this.announcer.announceStatus('Form submitted successfully');
            // Submit form
        } else {
            this.announcer.announceError('Please correct the errors in the form');
            this.focusFirstError();
        }
    }

    validateForm() {
        let isValid = true;
        let firstErrorField = null;

        this.fields.forEach((field) => {
            const fieldValid = this.validateField({ target: field });
            if (!fieldValid) {
                isValid = false;
                if (!firstErrorField) {
                    firstErrorField = field;
                }
            }
        });

        return isValid;
    }

    validateField(event) {
        const field = event.target;
        const errorElement = document.getElementById(`${field.id}-error`);
        let isValid = true;
        let errorMessage = '';

        // Remove existing error state
        field.setAttribute('aria-invalid', 'false');
        if (errorElement) {
            errorElement.textContent = '';
        }

        // Required field validation
        if (field.hasAttribute('required') && !field.value.trim()) {
            isValid = false;
            errorMessage = `${this.getFieldLabel(field)} is required`;
        }

        // Email validation
        if (field.type === 'email' && field.value && !this.isValidEmail(field.value)) {
            isValid = false;
            errorMessage = 'Please enter a valid email address';
        }

        // Phone validation
        if (field.type === 'tel' && field.value && !this.isValidPhone(field.value)) {
            isValid = false;
            errorMessage = 'Please enter a valid phone number';
        }

        // Set error state
        if (!isValid) {
            field.setAttribute('aria-invalid', 'true');
            if (errorElement) {
                errorElement.textContent = errorMessage;
            }
        }

        return isValid;
    }

    clearFieldError(event) {
        const field = event.target;
        const errorElement = document.getElementById(`${field.id}-error`);

        if (field.getAttribute('aria-invalid') === 'true') {
            field.setAttribute('aria-invalid', 'false');
            if (errorElement) {
                errorElement.textContent = '';
            }
        }
    }

    focusFirstError() {
        const firstErrorField = this.form.querySelector('[aria-invalid="true"]');
        if (firstErrorField) {
            firstErrorField.focus();
        }
    }

    getFieldLabel(field) {
        const label = this.form.querySelector(`label[for="${field.id}"]`);
        return label ? label.textContent.replace('*', '').trim() : field.name;
    }

    isValidEmail(email) {
        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailPattern.test(email);
    }

    isValidPhone(phone) {
        const phonePattern = /^\(\d{3}\)\s\d{3}-\d{4}$/;
        return phonePattern.test(phone);
    }
}

// Initialize form validation
document.querySelectorAll('.accessible-form').forEach((form) => {
    new AccessibleFormValidator(form);
});
```

