// Accessible tabs implementation
class AccessibleTabs {
    constructor(tabsContainer) {
        this.tabList = tabsContainer.querySelector('[role="tablist"]');
        this.tabs = Array.from(tabsContainer.querySelectorAll('[role="tab"]'));
        this.panels = Array.from(tabsContainer.querySelectorAll('[role="tabpanel"]'));
        this.currentIndex = 0;

        this.bindEvents();
    }

    bindEvents() {
        this.tabs.forEach((tab, index) => {
            tab.addEventListener('click', () => this.activateTab(index));
            tab.addEventListener('keydown', (e) => this.handleKeydown(e, index));
        });
    }

    activateTab(index) {
        // Deactivate all tabs and panels
        this.tabs.forEach((tab, i) => {
            tab.setAttribute('aria-selected', 'false');
            tab.setAttribute('tabindex', '-1');
            this.panels[i].setAttribute('hidden', '');
        });

        // Activate selected tab and panel
        this.tabs[index].setAttribute('aria-selected', 'true');
        this.tabs[index].setAttribute('tabindex', '0');
        this.tabs[index].focus();
        this.panels[index].removeAttribute('hidden');

        this.currentIndex = index;
    }

    handleKeydown(event, index) {
        let newIndex;

        switch (event.key) {
            case 'ArrowLeft':
                newIndex = index > 0 ? index - 1 : this.tabs.length - 1;
                this.activateTab(newIndex);
                event.preventDefault();
                break;
            case 'ArrowRight':
                newIndex = index < this.tabs.length - 1 ? index + 1 : 0;
                this.activateTab(newIndex);
                event.preventDefault();
                break;
            case 'Home':
                this.activateTab(0);
                event.preventDefault();
                break;
            case 'End':
                this.activateTab(this.tabs.length - 1);
                event.preventDefault();
                break;
        }
    }
}

// Initialize all tab components
document.querySelectorAll('.tabs').forEach((tabs) => {
    new AccessibleTabs(tabs);
});
