// Automated accessibility testing with Jest and React Testing Library
import { render, screen } from '@testing-library/react';
import { axe, toHaveNoViolations } from 'jest-axe';
import UserForm from './UserForm';

expect.extend(toHaveNoViolations);

describe('UserForm Accessibility', () => {
    test('should not have accessibility violations', async () => {
        const { container } = render(<UserForm />);
        const results = await axe(container);
        expect(results).toHaveNoViolations();
    });

    test('should have proper form labels', () => {
        render(<UserForm />);

        expect(screen.getByLabelText(/email/i)).toBeInTheDocument();
        expect(screen.getByLabelText(/password/i)).toBeInTheDocument();
        expect(screen.getByRole('button', { name: /submit/i })).toBeInTheDocument();
    });

    test('should have proper ARIA attributes', () => {
        render(<UserForm />);

        const emailField = screen.getByLabelText(/email/i);
        expect(emailField).toHaveAttribute('aria-required', 'true');
        expect(emailField).toHaveAttribute('aria-invalid', 'false');
    });

    test('should handle keyboard navigation', () => {
        render(<UserForm />);

        const emailField = screen.getByLabelText(/email/i);
        const passwordField = screen.getByLabelText(/password/i);
        const submitButton = screen.getByRole('button', { name: /submit/i });

